package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import static org.jsoup.nodes.NodeVisitor.*;
import static org.junit.Assert.*;

public class Node_previousSibling_TriageGen2Test {

    @Test
    public void testPreviousSibling_NoSiblings_ReturnsNull() {
        Node node = new Element("test");
        assertNull(node.previousSibling());
    }

    @Test
    public void testPreviousSibling_SingleSibling_ReturnsSibling() {
        Node node = new Element("test");
        Node sibling = new Element("sibling");
        node.appendChild(sibling);
        assertEquals(sibling, node.previousSibling());
    }

    @Test
    public void testPreviousSibling_MultipleSiblings_ReturnsSecondLastSibling() {
        Node node = new Element("test");
        Node sibling1 = new Element("sibling1");
        Node sibling2 = new Element("sibling2");
        Node sibling3 = new Element("sibling3");
        node.appendChild(sibling1);
        node.appendChild(sibling2);
        node.appendChild(sibling3);
        assertEquals(sibling2, node.previousSibling());
    }

    @Test
    public void testPreviousSibling_EmptyList_ReturnsNull() {
        Node node = new Element("test");
        List<Node> siblings = new ArrayList<>();
        node.childNodes = siblings;
        assertNull(node.previousSibling());
    }

    @Test
    public void testPreviousSibling_NullList_ReturnsNull() {
        Node node = new Element("test");
        List<Node> siblings = null;
        node.childNodes = siblings;
        assertNull(node.previousSibling());
    }

    @Test
    public void testPreviousSibling_IndexOutOfBounds_ReturnsNull() {
        Node node = new Element("test");
        List<Node> siblings = new ArrayList<>();
        node.childNodes = siblings;
        node.siblingIndex = siblings.size() + 1;
        assertNull(node.previousSibling());
    }

    @Test
    public void testPreviousSibling_IndexZero_ReturnsNull() {
        Node node = new Element("test");
        List<Node> siblings = new ArrayList<>();
        node.childNodes = siblings;
        node.siblingIndex = 0;
        assertNull(node.previousSibling());
    }

    @Test
    public void testPreviousSibling_ValidIndex_ReturnsSibling() {
        Node node = new Element("test");
        List<Node> siblings = new ArrayList<>();
        siblings.add(new Element("sibling"));
        node.childNodes = siblings;
        node.siblingIndex = 1;
        assertEquals(siblings.get(0), node.previousSibling());
    }
}
